# Cloud-Native Service Mesh Sidecar Proxy in C#

Below is a comprehensive implementation of a modular sidecar proxy in C# that handles mTLS, load balancing, and Prometheus metrics. This implementation uses ASP.NET Core for the HTTP server and integrates with common service mesh concepts.

## Core Architecture

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Net.Security;
using System.Security.Authentication;
using System.Security.Cryptography.X509Certificates;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Prometheus;

public class ServiceMeshSidecarProxy
{
    private readonly ILogger<ServiceMeshSidecarProxy> _logger;
    private readonly IConfiguration _config;
    private readonly IServiceProvider _serviceProvider;

    // Configuration
    private readonly string _serviceName;
    private readonly string _servicePort;
    private readonly string _mtlsCaCertPath;
    private readonly string _mtlsClientCertPath;
    private readonly string _mtlsClientKeyPath;
    private readonly string _metricsPort;
    private readonly string _upstreamServiceName;
    private readonly List<string> _upstreamInstances;

    // Components
    private readonly InboundTrafficInterceptor _inboundInterceptor;
    private readonly LoadBalancingPolicyEngine _loadBalancer;
    private readonly TelemetryReporter _telemetryReporter;

    // Metrics
    private readonly Counter _requestCount;
    private readonly Counter _requestLatency;
    private readonly Counter _mtlsHandshakeCount;
    private readonly Counter _mtlsHandshakeErrors;

    public ServiceMeshSidecarProxy(
        ILogger<ServiceMeshSidecarProxy> logger,
        IConfiguration config,
        IServiceProvider serviceProvider)
    {
        _logger = logger;
        _config = config;
        _serviceProvider = serviceProvider;

        // Load configuration
        _serviceName = _config["ServiceName"];
        _servicePort = _config["ServicePort"];
        _mtlsCaCertPath = _config["MTLS:CaCertPath"];
        _mtlsClientCertPath = _config["MTLS:ClientCertPath"];
        _mtlsClientKeyPath = _config["MTLS:ClientKeyPath"];
        _metricsPort = _config["MetricsPort"];
        _upstreamServiceName = _config["UpstreamServiceName"];
        _upstreamInstances = _config.GetSection("UpstreamInstances").Get<List<string>>();

        // Initialize components
        _inboundInterceptor = new InboundTrafficInterceptor(
            _logger,
            _mtlsCaCertPath,
            _mtlsClientCertPath,
            _mtlsClientKeyPath);

        _loadBalancer = new LoadBalancingPolicyEngine(
            _logger,
            _upstreamInstances,
            new RoundRobinPolicy(),
            new LeastLatencyPolicy());

        _telemetryReporter = new TelemetryReporter(
            _logger,
            _metricsPort,
            new HttpClient());

        // Initialize metrics
        _requestCount = Metrics.CreateCounter("service_mesh_requests_total", "Total number of requests");
        _requestLatency = Metrics.CreateHistogram("service_mesh_request_latency_seconds", "Request latency in seconds");
        _mtlsHandshakeCount = Metrics.CreateCounter("service_mesh_mtls_handshakes_total", "Total mTLS handshakes");
        _mtlsHandshakeErrors = Metrics.CreateCounter("service_mesh_mtls_handshake_errors_total", "Failed mTLS handshakes");
    }

    public void Run()
    {
        var builder = WebApplication.CreateBuilder(new WebApplicationOptions
        {
            Args = Array.Empty<string>(),
            ContentRootPath = AppContext.BaseDirectory,
            EnvironmentName = Environments.Production
        });

        // Add services
        builder.Services.AddSingleton(_logger);
        builder.Services.AddSingleton(_config);
        builder.Services.AddSingleton(_serviceProvider);
        builder.Services.AddSingleton(_inboundInterceptor);
        builder.Services.AddSingleton(_loadBalancer);
        builder.Services.AddSingleton(_telemetryReporter);

        // Add metrics endpoint
        builder.Services.AddPrometheusMetrics();

        var app = builder.Build();

        // Configure middleware
        app.UseRouting();

        app.Use(async (context, next) =>
        {
            var stopwatch = System.Diagnostics.Stopwatch.StartNew();

            try
            {
                // 1. Inbound Traffic Interception (mTLS)
                var clientCert = await _inboundInterceptor.ValidateClientCertificate(context);
                _mtlsHandshakeCount.Inc();

                // 2. Load Balancing
                var upstreamInstance = _loadBalancer.SelectInstance(clientCert?.Subject);
                var upstreamUri = new Uri($"https://{upstreamInstance}:443");

                // 3. Forward request
                using var httpClient = new HttpClient(new SocketsHttpHandler
                {
                    SslOptions = new SslClientAuthenticationOptions
                    {
                        ApplicationProtocols = { new SslApplicationProtocolNegotiationOption("h2") }
                    }
                });

                httpClient.DefaultRequestHeaders.Add("X-Forwarded-For", context.Connection.RemoteIpAddress.ToString());
                httpClient.DefaultRequestHeaders.Add("X-Forwarded-Proto", "https");

                var request = new HttpRequestMessage
                {
                    Method = new HttpMethod(context.Request.Method),
                    RequestUri = upstreamUri,
                    Version = HttpVersion.Version20
                };

                foreach (var header in context.Request.Headers)
                {
                    request.Headers.TryAddWithoutValidation(header.Key, header.Value.ToArray());
                }

                request.Content = context.Request.Body is not null
                    ? new StreamContent(context.Request.Body)
                    : null;

                var response = await httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, context.RequestAborted);

                // 4. Telemetry
                _requestCount.Inc();
                _requestLatency.Observe(stopwatch.Elapsed.TotalSeconds);

                context.Response.StatusCode = (int)response.StatusCode;
                foreach (var header in response.Headers)
                {
                    context.Response.Headers[header.Key] = header.Value.ToArray();
                }

                await response.Content.CopyToAsync(context.Response.Body);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Request failed");
                _mtlsHandshakeErrors.Inc();
                context.Response.StatusCode = 500;
                await context.Response.WriteAsync("Internal server error");
            }
            finally
            {
                stopwatch.Stop();
            }
        });

        // Start metrics server
        _telemetryReporter.Start();

        app.Run();
    }
}
```

