## 2. Load Balancing Policy Engine

```csharp
public interface ILoadBalancingPolicy
{
    string SelectInstance(List<string> instances, string clientInfo);
}

public class RoundRobinPolicy : ILoadBalancingPolicy
{
    private readonly ConcurrentDictionary<string, int> _instanceIndices = new();
    private readonly object _lock = new();

    public string SelectInstance(List<string> instances, string clientInfo)
    {
        if (instances == null || instances.Count == 0)
            throw new InvalidOperationException("No instances available");

        // Use client info as key for round-robin
        var key = clientInfo ?? "default";
        int index;

        lock (_lock)
        {
            if (!_instanceIndices.TryGetValue(key, out index))
            {
                index = 0;
                _instanceIndices[key] = 0;
            }
            else
            {
                index = (_instanceIndices[key] + 1) % instances.Count;
                _instanceIndices[key] = index;
            }
        }

        return instances[index];
    }
}

public class LeastLatencyPolicy : ILoadBalancingPolicy
{
    private readonly ConcurrentDictionary<string, double> _latencyMetrics = new();
    private readonly object _lock = new();

    public string SelectInstance(List<string> instances, string clientInfo)
    {
        if (instances == null || instances.Count == 0)
            throw new InvalidOperationException("No instances available");

        // In a real implementation, you would track actual latency metrics
        // This is a simplified version that just returns the first instance

        // For actual implementation, you would:
        // 1. Track response times for each instance
        // 2. Select the instance with the lowest average latency

        return instances[0];
    }
}

public class LoadBalancingPolicyEngine
{
    private readonly ILogger _logger;
    private readonly List<string> _instances;
    private readonly ILoadBalancingPolicy _primaryPolicy;
    private readonly ILoadBalancingPolicy _fallbackPolicy;

    public LoadBalancingPolicyEngine(
        ILogger logger,
        List<string> instances,
        ILoadBalancingPolicy primaryPolicy,
        ILoadBalancingPolicy fallbackPolicy)
    {
        _logger = logger;
        _instances = instances ?? throw new ArgumentNullException(nameof(instances));
        _primaryPolicy = primaryPolicy ?? throw new ArgumentNullException(nameof(primaryPolicy));
        _fallbackPolicy = fallbackPolicy ?? throw new ArgumentNullException(nameof(fallbackPolicy));
    }

    public string SelectInstance(string clientInfo)
    {
        try
        {
            // Try primary policy first
            var instance = _primaryPolicy.SelectInstance(_instances, clientInfo);

            // In a real implementation, you would check if the instance is healthy
            // and fall back to the secondary policy if needed

            return instance;
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Primary load balancing policy failed, falling back to secondary");
            return _fallbackPolicy.SelectInstance(_instances, clientInfo);
        }
    }
}
