## 3. Telemetry Reporter (Prometheus)

```csharp
public class TelemetryReporter
{
    private readonly ILogger _logger;
    private readonly string _metricsPort;
    private readonly HttpClient _httpClient;
    private readonly Task _metricsServerTask;

    public TelemetryReporter(
        ILogger logger,
        string metricsPort,
        HttpClient httpClient)
    {
        _logger = logger;
        _metricsPort = metricsPort;
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));

        // Start metrics server
        _metricsServerTask = Task.Run(() => StartMetricsServer());
    }

    private async Task StartMetricsServer()
    {
        var server = new HttpListener();
        server.Prefixes.Add($"http://localhost:{_metricsPort}/metrics");
        server.Start();

        _logger.LogInformation("Metrics server started on port {Port}", _metricsPort);

        try
        {
            while (true)
            {
                var context = await server.GetContextAsync();
                var response = context.Response;
                response.ContentType = "text/plain; version=0.0.4";
                await response.WriteAsync(Metrics.DefaultRegistry.GetSampleMetrics());
                response.Close();
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Metrics server failed");
        }
        finally
        {
            server.Stop();
        }
    }

    public void Start()
    {
        _metricsServerTask.GetAwaiter().GetResult();
    }
}
```

